-- dwh.lu_place -- full snapshot, 6655 rows, taken 2026-09-18.
--
-- THIS IS THE BACKUP. It reloads the table from nothing. Regenerate after any
-- batch of edits:
--   SELECT cityname, citynamenorm, county, stateabbr, countyfipscode,
--          citycode, citydisplayname, notes
--   FROM dwh.lu_place ORDER BY stateabbr, countyfipscode, citynamenorm;
--
-- The table itself is created by CICD from src/artifacts/sql/dwh/lu_place_ddl.sql.
-- This file only loads data, and names its columns explicitly, so it does not
-- care what order the DDL declares them in.
--
-- Join key:       (stateabbr, countyfipscode, citynamenorm)
-- Place identity: (stateabbr, citycode) -- NEVER citycode alone
-- Prefixes:       none = DOT, T = township split off a DOT code,
--                 L = minted for a place in neither source
-- Coded rows:     6270 of 6655
-- Dropdown:       5176 distinct places, 5798 distinct labels

TRUNCATE dwh.lu_place;
















COMMIT;

-- Validation: both must return zero rows.

-- duplicate join keys
SELECT stateabbr, countyfipscode, citynamenorm, COUNT(*)
FROM dwh.lu_place GROUP BY 1,2,3 HAVING COUNT(*) > 1;

-- two places sharing one dropdown label
SELECT displayname, COUNT(*) FROM (
  SELECT stateabbr, citycode, MIN(citydisplayname) AS displayname
  FROM dwh.lu_place WHERE citycode IS NOT NULL GROUP BY 1,2
) GROUP BY 1 HAVING COUNT(*) > 1;
